"""news-image-20261117 entry (Python 3.13, standard library only).

Writes the image that sums up Tuesday 17 November 2026's world news
to /output/entry.png. The image is embedded below as base64 (JPEG bytes,
kept under the name entry.png, as the competition allows) and written out
byte for byte, so both runs produce identical output. No network access.
"""

import base64
import os


IMAGE_B64 = ""

OUTPUT_DIR = os.environ.get("MAKEFUN_OUTPUT_DIR", "/output")

os.makedirs(OUTPUT_DIR, exist_ok=True)

# Bytes, not text mode: text mode would write the platform's line ends.
with open(os.path.join(OUTPUT_DIR, "entry.png"), "wb") as f:
    f.write(base64.b64decode(IMAGE_B64))
